sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var shouldRecall = true;
        var child = new GlideRecord("x_hsb11_mss_smh_child_aggregated_trade_chat_queue");
        child.addQuery('trade_case_task', current.sys_id);
        child.query();
        if (child.next()) {
            if (child.parent.aggregation_status == 'Draft') { // no need to recall if message is not sent yet
                shouldRecall = false;
            }
            if (child.parent.trade_count != 1) { // if trade_count is more than 1, the message should be recalled only when trade are auto resolved. 
                var brother = new GlideRecord('x_hsb11_mss_smh_child_aggregated_trade_chat_queue');
                brother.addQuery('parent', child.parent);
                brother.query();
                while (brother.next()) {
                    if (brother.getValue('actioned') != 1) {
                        shouldRecall = false;
                        break;
                    }
                    if (brother.getValue('symphony_response') != 'Exception resolved') {
                        shouldRecall = false;
                        break;
                    }
                }
            }

            if (shouldRecall) { // Create a new record to recall the message.
                var OutboundtaskNew = new GlideRecord("x_hsb11_mss_sw_hsbc_outbound_symphony_message_log");
                OutboundtaskNew.initialize();
                OutboundtaskNew.message_body = child.parent.encryptedmessageid;
                OutboundtaskNew.type = "Recall";
                OutboundtaskNew.setValue("active", true);
                OutboundtaskNew.setValue("servicenow_task_id", current.sys_id);
                OutboundtaskNew.state = "Ready to be sent";
                OutboundtaskNew.source = 'Equities';
                OutboundtaskNew.insert();
            }
        }
    } catch (e) {
        gs.error('[BR][HSBC- Recall for cancellation]: ' + e.getMessage());
    }
})(current, previous);
